 71→// updateModel is a test helper that sends a message and returns the updated searchModel.
 72→func updateModel(t *testing.T, m searchModel, msg tea.Msg) searchModel {
 73→	t.Helper()
 74→	updated, _ := m.Update(msg)
 75→	result, ok := updated.(searchModel)
 76→	if !ok {
 77→		t.Fatalf("Update returned %T, want searchModel", updated)
 78→	}
 79→	return result
 80→}
